CREATE FUNCTION public.active_season() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE sid uuid; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF; SELECT c.season_id INTO sid FROM public.user_preferences p JOIN public.challenges c ON c.id=p.active_challenge_id JOIN public.season_entries e ON e.season_id=c.season_id AND e.user_id=auth.uid() WHERE p.user_id=auth.uid(); RETURN (SELECT to_jsonb(s) FROM public.seasons s WHERE CASE WHEN sid IS NOT NULL THEN s.id=sid ELSE s.status='live' AND NOT s.challenge_owned END ORDER BY starts_on LIMIT 1); END $$;
CREATE FUNCTION public.activate_challenge(_id uuid DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF; IF _id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.challenges c JOIN public.season_entries e ON e.season_id=c.season_id WHERE c.id=_id AND e.user_id=auth.uid()) THEN RAISE EXCEPTION 'forbidden'; END IF; INSERT INTO public.user_preferences(user_id,active_challenge_id) VALUES(auth.uid(),_id) ON CONFLICT(user_id) DO UPDATE SET active_challenge_id=_id; END $$;
CREATE FUNCTION public.create_challenge(_name text,_template text,_days integer,_audience text,_same_habits boolean,_habit_keys text[],_faith_allowed boolean,_weekly_bosses boolean,_public_board boolean,_starts_on date DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE uid uuid:=auth.uid(); sid uuid; cid uuid; crid uuid; vcode text; sd date; cap integer; BEGIN
IF uid IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;
IF _template NOT IN ('winter_arc','ramadan','summer_body','reading','steps','custom') OR _audience NOT IN ('solo','duo','squad','club','company','creator') OR _days NOT BETWEEN 7 AND 90 OR char_length(trim(_name)) NOT BETWEEN 1 AND 60 OR cardinality(_habit_keys) NOT BETWEEN 1 AND 3 OR cardinality(_habit_keys)<>(SELECT count(DISTINCT k) FROM unnest(_habit_keys) k) THEN RAISE EXCEPTION 'invalid_challenge'; END IF;
IF _template<>'custom' AND _days<>(CASE _template WHEN 'winter_arc' THEN 40 WHEN 'ramadan' THEN 30 WHEN 'summer_body' THEN 45 WHEN 'reading' THEN 21 WHEN 'steps' THEN 30 END) THEN RAISE EXCEPTION 'invalid_duration'; END IF;
IF _audience='creator' AND NOT public.has_role(uid,'creator') THEN RAISE EXCEPTION 'creator_required'; END IF; IF _audience IN ('club','company') THEN RAISE EXCEPTION 'contact_required'; END IF;
IF EXISTS(SELECT 1 FROM unnest(_habit_keys) k LEFT JOIN public.habit_templates h ON h.key=k WHERE h.id IS NULL OR (h.is_faith AND NOT _faith_allowed)) THEN RAISE EXCEPTION 'invalid_habits'; END IF;
PERFORM pg_advisory_xact_lock(hashtext(uid::text||'challenge')); IF (SELECT count(*) FROM public.challenges WHERE owner_id=uid AND created_at>now()-interval '1 day')>=10 THEN RAISE EXCEPTION 'challenge_limit'; END IF;
sd:=coalesce(_starts_on,public._local_today(uid)); IF sd<public._local_today(uid) THEN RAISE EXCEPTION 'invalid_start'; END IF;
LOOP vcode:=upper(substr(replace(gen_random_uuid()::text,'-',''),1,6)); EXIT WHEN NOT EXISTS(SELECT 1 FROM public.challenges WHERE code=vcode) AND NOT EXISTS(SELECT 1 FROM public.crews WHERE code=vcode); END LOOP;
INSERT INTO public.seasons(slug,name,starts_on,ends_on,status,theme_color,challenge_owned) VALUES('challenge-'||lower(vcode),jsonb_build_object('en',trim(_name),'fr',trim(_name),'ar',trim(_name),'aeb',trim(_name)),sd,sd+_days-1,'live','blue',true) RETURNING id INTO sid;
IF _audience<>'solo' THEN cap:=CASE _audience WHEN 'duo' THEN 2 WHEN 'squad' THEN 10 ELSE 50 END; INSERT INTO public.crews(season_id,name,code,owner_id,kind,max_members,is_public) VALUES(sid,trim(_name),vcode,uid,_audience,cap,_public_board) RETURNING id INTO crid; INSERT INTO public.crew_members(crew_id,user_id,role) VALUES(crid,uid,'owner'); END IF;
INSERT INTO public.challenges(owner_id,season_id,name,template,days,audience,same_habits,habit_keys,faith_allowed,weekly_bosses,public_board,starts_on,code,crew_id) VALUES(uid,sid,trim(_name),_template,_days,_audience,_same_habits,_habit_keys,_faith_allowed,_weekly_bosses,_public_board,sd,vcode,crid) RETURNING id INTO cid;
INSERT INTO public.season_entries(user_id,season_id,mode) VALUES(uid,sid,CASE WHEN _audience='solo' THEN 'solo' ELSE 'crew' END);
INSERT INTO public.user_habits(user_id,season_id,template_id,kind,target,unit,position) SELECT uid,sid,h.id,h.kind,h.default_target,h.unit,k.ord::integer-1 FROM unnest(_habit_keys) WITH ORDINALITY k(key,ord) JOIN public.habit_templates h ON h.key=k.key;
IF _weekly_bosses THEN INSERT INTO public.bosses(season_id,week_no,slug,name,rule,metric,exercise_key,levels,starts_at,ends_at,color) SELECT sid,w,'week-'||w,jsonb_build_object('en','Show Up','fr','Présent !','ar','كن حاضرًا','aeb','احضر'),jsonb_build_object('en','Complete your habits on 5 days this week.','fr','Termine tes habitudes 5 jours cette semaine.','ar','أكمل عاداتك في 5 أيام هذا الأسبوع.','aeb','كمّل عاداتك 5 أيّام هالجمعة.'),'days','completion','[{"key":"rookie","target":3,"bonus":50},{"key":"pro","target":5,"bonus":100},{"key":"beast","target":7,"bonus":150}]',((sd+(w-1)*7)::timestamp AT TIME ZONE 'Africa/Tunis'),((least(sd+w*7,sd+_days))::timestamp AT TIME ZONE 'Africa/Tunis')-interval '1 second','orange' FROM generate_series(1,ceil(_days/7.0)::int) w; END IF;
PERFORM public.activate_challenge(cid); RETURN jsonb_build_object('id',cid,'code',vcode,'season_id',sid,'audience',_audience); END $$;
CREATE FUNCTION public.challenge_preview(_code text) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT jsonb_build_object('name',c.name,'days',c.days,'audience',c.audience,'starts_on',c.starts_on,'code',c.code,'members',(SELECT count(*) FROM public.season_entries e WHERE e.season_id=c.season_id),'full',c.audience='solo' OR (SELECT count(*) FROM public.season_entries e WHERE e.season_id=c.season_id)>=coalesce(cr.max_members,1),'ended',s.ends_on<current_date) FROM public.challenges c JOIN public.seasons s ON s.id=c.season_id LEFT JOIN public.crews cr ON cr.id=c.crew_id WHERE c.code=upper(trim(_code)) $$;
CREATE FUNCTION public.join_challenge(_code text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE uid uuid:=auth.uid(); c public.challenges; cap integer; BEGIN IF uid IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF; SELECT * INTO c FROM public.challenges WHERE code=upper(trim(_code)) FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'crew_not_found'; END IF; IF EXISTS(SELECT 1 FROM public.season_entries WHERE user_id=uid AND season_id=c.season_id) THEN PERFORM public.activate_challenge(c.id); RETURN c.id; END IF; IF c.audience='solo' OR (SELECT ends_on FROM public.seasons WHERE id=c.season_id)<public._local_today(uid) THEN RAISE EXCEPTION 'forbidden'; END IF; SELECT max_members INTO cap FROM public.crews WHERE id=c.crew_id; IF (SELECT count(*) FROM public.season_entries WHERE season_id=c.season_id)>=cap THEN RAISE EXCEPTION 'crew_full'; END IF; INSERT INTO public.crew_members(crew_id,user_id) VALUES(c.crew_id,uid); INSERT INTO public.season_entries(user_id,season_id,mode) VALUES(uid,c.season_id,'crew'); INSERT INTO public.user_habits(user_id,season_id,template_id,kind,target,unit,position) SELECT uid,c.season_id,h.id,h.kind,h.default_target,h.unit,k.ord::integer-1 FROM unnest(c.habit_keys) WITH ORDINALITY k(key,ord) JOIN public.habit_templates h ON h.key=k.key; PERFORM public.activate_challenge(c.id); RETURN c.id; END $$;
CREATE FUNCTION public.create_sub_squad(_challenge uuid,_name text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE sid uuid; BEGIN IF NOT EXISTS(SELECT 1 FROM public.challenges WHERE id=_challenge AND owner_id=auth.uid() AND audience='company') OR char_length(trim(_name)) NOT BETWEEN 1 AND 40 THEN RAISE EXCEPTION 'forbidden'; END IF; INSERT INTO public.challenge_squads(challenge_id,name) VALUES(_challenge,trim(_name)) RETURNING id INTO sid; RETURN sid; END $$;
CREATE FUNCTION public.assign_sub_squad(_squad uuid,_user uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c public.challenges; BEGIN SELECT ch.* INTO c FROM public.challenge_squads s JOIN public.challenges ch ON ch.id=s.challenge_id WHERE s.id=_squad FOR UPDATE OF ch; IF c.owner_id IS DISTINCT FROM auth.uid() OR NOT EXISTS(SELECT 1 FROM public.season_entries WHERE season_id=c.season_id AND user_id=_user) THEN RAISE EXCEPTION 'forbidden'; END IF; IF (SELECT count(*) FROM public.challenge_squad_members WHERE squad_id=_squad)>=10 THEN RAISE EXCEPTION 'crew_full'; END IF; DELETE FROM public.challenge_squad_members WHERE user_id=_user AND squad_id IN (SELECT id FROM public.challenge_squads WHERE challenge_id=c.id); INSERT INTO public.challenge_squad_members VALUES(_squad,_user); END $$;
CREATE FUNCTION public.validate_challenge_habit() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c public.challenges; h public.habit_templates; BEGIN SELECT * INTO c FROM public.challenges WHERE season_id=NEW.season_id; IF FOUND THEN SELECT * INTO h FROM public.habit_templates WHERE id=NEW.template_id; IF (h.is_faith AND NOT c.faith_allowed) OR (c.same_habits AND (h.key IS NULL OR NOT h.key=ANY(c.habit_keys) OR NOT NEW.active OR NEW.target<>h.default_target OR NEW.kind<>h.kind)) THEN RAISE EXCEPTION 'challenge_habits_locked'; END IF; END IF; RETURN NEW; END $$; CREATE TRIGGER challenge_habit_guard BEFORE INSERT OR UPDATE ON public.user_habits FOR EACH ROW EXECUTE FUNCTION public.validate_challenge_habit();
REVOKE ALL ON FUNCTION public.active_season(),public.activate_challenge(uuid),public.create_challenge(text,text,integer,text,boolean,text[],boolean,boolean,boolean,date),public.join_challenge(text),public.create_sub_squad(uuid,text),public.assign_sub_squad(uuid,uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.active_season(),public.activate_challenge(uuid),public.create_challenge(text,text,integer,text,boolean,text[],boolean,boolean,boolean,date),public.join_challenge(text),public.create_sub_squad(uuid,text),public.assign_sub_squad(uuid,uuid) TO authenticated; REVOKE ALL ON FUNCTION public.challenge_preview(text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.challenge_preview(text) TO anon,authenticated;